sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
from authoring import finish,ref,step,paragraph
finish('polylog-pass-directed-reachability',
 id='TCS-6556',title='Directed reachability with nearly linear memory and polylogarithmic passes',area='Distributed, parallel and sublinear algorithms',criterion='resources',question_type='yes_no',
 formal='Do there exist constants a,b,C and a uniform randomized streaming algorithm that decides directed s–t reachability on every n-vertex graph using at most Cn(log(n+2))^a bits of memory and C(log(n+2))^b passes, with success probability at least 2/3 for every adversarially ordered edge stream?',
 definitions='The input is a finite simple directed graph on the labelled vertex set [n], n≥2, with distinct designated vertices s,t. The algorithm knows n,s,t before reading the edges. Each directed edge occurs once in an insertion-only stream, in an arbitrary order fixed independently of the algorithm’s random bits. Each pass scans this same stream in the same forward order. The input is read-only: there are no adjacency queries, random-access reads, sorting operations on external storage, or writable auxiliary streams. All mutable working storage counts toward the bit bound; fresh independent random bits may be read from a one-way random source. The memory and pass bounds hold on every execution. Computation between successive input items is unrestricted but must terminate; no running-time bound beyond termination is imposed. A yes answer means that there is a directed path from s to t in the input graph. The constants and algorithm are independent of n, the graph, and the edge order.',
 answer_criterion='Construct such an algorithm with a proof of its memory, pass and per-input error guarantees, or prove that no algorithm satisfies the stated existential bounds. A lower bound of Ω(log n/log log n) passes, or any fixed polylogarithmic bound, is compatible with a positive answer. A superpolylogarithmic pass lower bound throughout the allowed nearly linear memory range would refute it. Solving only undirected graphs, random-order streams, or a restricted class of digraphs does not suffice.',
 context=[
 paragraph('Directed reachability asks an elementary question: can one vertex eventually lead to another by following arrows? With the whole graph in memory, a search answers it in linear time. In a graph stream, the difficulty is that the next useful edge may already have gone past before the algorithm learns that its tail is reachable. Repeated scans provide another opportunity to use the edge, but every scan revisits the entire input.'),
 paragraph('Nearly linear memory means linear in the number of vertices, up to powers of a logarithm. It can store labels, several values per vertex and a sparse auxiliary graph, but a dense input may have quadratically many edges. The card allows every fixed polylogarithmic memory overhead: it does not ask for an especially restrictive exact n-bit implementation. Conversely, allowing storage proportional to all the edges would erase the intended obstacle.'),
 paragraph('A simple baseline maintains the set of vertices already reached from s. Whenever an edge leaves this set, its head is marked reachable. After at most n−1 scans every reachable vertex has been found, using a bit per vertex and counters. A path whose edges appear in reverse path order makes this particular algorithm advance slowly. That example is not a lower bound for all algorithms: a path has only linearly many edges and fits entirely in the permitted memory.'),
 paragraph('The undirected analogue has a much stronger one-pass solution: maintain connected components with union–find. Direction removes the equivalence-relation structure that makes this summary sufficient. Strongly connected components can still be contracted in a digraph, but their directed reachability relation is another graph rather than just a partition. A small summary must somehow preserve the information needed for the specified source and target.'),
 paragraph('Jambulapati, Liu and Sidford give a randomized parallel reachability algorithm using nearly linear work and n^{1/2+o(1)} depth. Their shortcut construction can also be implemented in the streaming model. Assadi and coauthors explicitly state the resulting n^{1/2+o(1)}-pass semi-streaming path-finding algorithm as Proposition 4. This supplies the relevant upper bound through a concrete simulation, rather than through an assumption that every shallow parallel computation automatically yields a streaming algorithm.','upper'),
 paragraph('The shortcuts preserve which pairs are reachable while reducing how many edges a useful path needs. They can be stored because there are only nearly linearly many of them. This explains why the upper bound is much better than repeated ordinary reachability propagation. It also exposes a possible source of new ideas: construct better shortcuts within the streaming resources, or find a method that does not depend on such a shortcut set.'),
 paragraph('On the lower-bound side, Guruswami and Onak extend earlier path-output barriers to the decision problem itself. Their multipass space bound implies that semi-streaming reachability requires Ω(log n/log log n) passes. The exact theorem includes polynomial factors in the pass count and logarithmic factors in n; these should not be dropped when comparing parameters. The conclusion rules out constant passes but leaves the polylogarithmic target available.','go'),
 paragraph('Chen, Kol, Paramonov, Saxena, Song and Yu prove that o(√log n) passes require n^{2−o(1)} space. This is a striking strengthening of how much memory is necessary when the pass budget is very small. It is not a larger asymptotic lower bound on the number of passes with nearly linear memory than the Ω(log n/log log n) statement above. The two results describe different parts of the tradeoff.','lower'),
 paragraph('Azarmehr and coauthors’ September 9, 2026 revision still identifies n^{1/2+o(1)} as the fastest known semi-streaming reachability pass bound. Their Theorem 9 links an improved streaming approximation for distance to monotonicity to an improved reachability algorithm. This is evidence that the question controls progress beyond reachability itself, and gives a recent explicit check of the benchmark used on this card.','recent'),
 paragraph('A positive answer would show that repeated sequential access with a compact memory can recover global directed information surprisingly quickly. A negative answer would establish a fundamental barrier to that access pattern, even without restricting local computation time. Either result would help explain the difference between graph problems admitting compact summaries and those that require many rounds of discovering dependencies.')],
 why='Determine whether global directed reachability can be recovered from repeated sequential scans with only nearly linear memory, a central unresolved graph-streaming tradeoff.',
 importance=dict(score=95,method='editorial',assessed_on='2026-09-11',reason='A basic directed-graph primitive with a polynomial-versus-polylogarithmic pass gap, connections to communication lower bounds and consequences for other streaming tasks.'),
 progress=[step('2013–2016','Guruswami–Onak establish multipass superlinear space lower bounds for directed reachability decision; these imply Ω(log n/log log n) passes in semi-streaming space.','go'),step('2019','Jambulapati–Liu–Sidford develop nearly linear-work, approximately square-root-depth parallel reachability and its sparse shortcut construction.','parallel'),step('2021','Chen and coauthors prove almost-quadratic space is necessary for o(√log n) passes, strengthening the few-pass space tradeoff.','lower'),step('2022','Assadi and coauthors state and explain the n^{1/2+o(1)}-pass semi-streaming implementation, including path recovery, in Proposition 4.','upper'),step('2023-09','Assadi’s survey records the gap and explains the transition from search lower bounds to reachability-decision lower bounds.','primary'),step('2026-09-09','The revised streaming-monotonicity paper retains the square-root reachability benchmark and reduces faster approximation to faster reachability.','recent')],
 references=[ref('primary','Recent Advances in Multi-Pass Graph Streaming Lower Bounds','Sepehr Assadi',2023,'https://par.nsf.gov/servlets/purl/10488812','Inherited reference; ACM SIGACT News 54(3), September 2023; discussion of pointer chasing, set chasing, and the directed reachability gap'),ref('go','Superlinear lower bounds for multipass graph processing','Venkatesan Guruswami; Krzysztof Onak',2016,'https://eccc.weizmann.ac.il/report/2013/002/revision/3/download/','ECCC TR13-002, revision 3, February 2016; introduction gives Ω(n^{1+1/(2p+2)}/(p^{20}log^{3/2}n)); CCC 2013 precursor'),ref('parallel','Parallel Reachability in Almost Linear Work and Square Root Depth','Arun Jambulapati; Yang P. Liu; Aaron Sidford',2019,'https://arxiv.org/abs/1905.08841','FOCS 2019; parallel algorithm and reachability-preserving shortcut construction'),ref('upper','Semi-Streaming Bipartite Matching in Fewer Passes and Optimal Space','Sepehr Assadi; Arun Jambulapati; Yujia Jin; Aaron Sidford; Kevin Tian',2022,'https://arxiv.org/abs/2011.03495','SODA 2022, 627–669; Proposition 4 and its subsequent implementation argument explicitly give semi-streaming directed reachability/path finding'),ref('lower','Almost Optimal Super-Constant-Pass Streaming Lower Bounds for Reachability','Lijie Chen; Gillat Kol; Dmitry Paramonov; Raghuvansh R. Saxena; Zhao Song; Huacheng Yu',2021,'https://par.nsf.gov/servlets/purl/10315017','STOC 2021, Theorem 1.1 and introduction; near-quadratic space for o(√log n) passes'),ref('recent','Streaming Algorithms for Monotonicity Testing','Amir Azarmehr; Soheil Behnezhad; Lily Chung; Alma Ghafari; Jane Lange; Ronitt Rubinfeld',2026,'https://arxiv.org/abs/2608.07073v2','First posted 7 August; revision 9 September 2026; introduction following Theorem 1 and Theorem 9 record the current reachability benchmark and reduction')],
 status='source_open',status_note='No polylogarithmic-pass semi-streaming algorithm or superpolylogarithmic lower bound settling the stated question was found through 11 September 2026. A 9 September 2026 primary source explicitly retains the n^{1/2+o(1)} upper bound. The card fixes randomized decision, adversarial fixed edge order, bit space and unrestricted terminating local computation.',formulation_reviewed_on='2026-09-11')
